"extends Node

# Autoload: GameManager
# Manages active planets, player reference, input fallbacks, and general game state.

var planets: Array[Node3D] = []
var player: CharacterBody3D = null
var player_in_ship: bool = false

func _ready() -> void:
	_setup_default_inputs()

func register_planet(planet: Node3D) -> void:
	if not planets.has(planet):
		planets.append(planet)

func unregister_planet(planet: Node3D) -> void:
	planets.erase(planet)

func get_nearest_planet(from_pos: Vector3) -> Node3D:
	if planets.is_empty():
		return null
	var nearest: Node3D = null
	var min_dist: float = INF
	for p in planets:
		if is_instance_valid(p):
			var dist = from_pos.distance_squared_to(p.global_position)
			if dist < min_dist:
				min_dist = dist
				nearest = p
	return nearest

# Programmatic fallback to ensure keys are mapped if project.godot doesn't have them
func _setup_default_inputs() -> void:
	_ensure_key_action("move_forward", [KEY_W, KEY_UP])
	_ensure_key_action("move_back", [KEY_S, KEY_DOWN])
	_ensure_key_action("move_left", [KEY_A, KEY_LEFT])
	_ensure_key_action("move_right", [KEY_D, KEY_RIGHT])
	_ensure_key_action("jump", [KEY_SPACE])
	_ensure_key_action("run", [KEY_SHIFT])
	_ensure_key_action("interact", [KEY_E])
	_ensure_key_action("pause", [KEY_ESCAPE])

func _ensure_key_action(action_name: StringName, keycodes: Array) -> void:
	if not InputMap.has_action(action_name):
		InputMap.add_action(action_name)
	for code in keycodes:
		var has_event = false
		for ev in InputMap.action_get_events(action_name):
			if ev is InputEventKey and ev.physical_keycode == code:
				has_event = true
				break
		if not has_event:
			var event = InputEventKey.new()
			event.physical_keycode = code
			InputMap.action_add_event(action_name, event)
"

"extends Node3D
class_name PlanetGravity

# PlanetGravity.gd
# Handles Mars spherical gravity and registers with GameManager.

@export var planet_name: String = "Mars"
@export var planet_radius: float = 60.0
@export var atmosphere_radius: float = 130.0
@export var gravity_strength: float = 5.8 # Floatier than Earth (~9.8) for kid exploration

@onready var gravity_area: Area3D = $GravityArea

func _ready() -> void:
	if GameManager:
		GameManager.register_planet(self)

	if gravity_area:
		gravity_area.gravity_space_override = Area3D.SPACE_OVERRIDE_REPLACE
		gravity_area.gravity_point = true
		gravity_area.gravity_point_center = Vector3.ZERO
		gravity_area.gravity = gravity_strength

func _exit_tree() -> void:
	if GameManager:
		GameManager.unregister_planet(self)

func get_gravity_direction(from_pos: Vector3) -> Vector3:
	return (global_position - from_pos).normalized()

func get_surface_normal(from_pos: Vector3) -> Vector3:
	return (from_pos - global_position).normalized()

func get_altitude(from_pos: Vector3) -> float:
	return from_pos.distance_to(global_position) - planet_radius
"

"extends Node3D

# CameraArm.gd
# Third-person orbital camera designed for spherical planetary navigation.

@export var mouse_sensitivity: float = 0.0025
@export var pitch_min: float = -75.0
@export var pitch_max: float = 65.0
@export var camera_distance: float = 4.5

