"extends CanvasLayer

# hud.gd
# Educational HUD for kids exploring Mars with jetpack and science discoveries.

@onready var fuel_bar: ProgressBar = $Control/BottomLeft/FuelContainer/FuelBar
@onready var fuel_label: Label = $Control/BottomLeft/FuelContainer/FuelLabel
@onready var popup_panel: PanelContainer = $Control/CenterPopup
@onready var popup_title: Label = $Control/CenterPopup/VBox/TitleLabel
@onready var popup_fact: Label = $Control/CenterPopup/VBox/FactLabel
@onready var close_hint: Label = $Control/CenterPopup/VBox/CloseHint

var active_tween: Tween = null

func _ready() -> void:
	popup_panel.visible = false

	# Connect to player if already instantiated
	await get_tree().process_frame
	if GameManager and GameManager.player:
		_bind_player(GameManager.player)

func _bind_player(player: PlayerController) -> void:
	player.fuel_changed.connect(_on_fuel_changed)
	_on_fuel_changed(player.current_fuel, player.max_fuel)

func _on_fuel_changed(current: float, max_val: float) -> void:
	if fuel_bar:
		fuel_bar.max_value = max_val
		fuel_bar.value = current
	if fuel_label:
		fuel_label.text = "JETPACK BOOST: %d%%" % int((current / max_val) * 100.0)

func show_discovery(title: String, fact: String) -> void:
	popup_title.text = "🚀 DISCOVERY: " + title
	popup_fact.text = fact
	popup_panel.visible = true
	popup_panel.modulate.a = 0.0

	if active_tween:
		active_tween.kill()

	active_tween = create_tween()
	active_tween.tween_property(popup_panel, "modulate:a", 1.0, 0.3)
	active_tween.tween_interval(6.0)
	active_tween.tween_property(popup_panel, "modulate:a", 0.0, 0.5)
	active_tween.tween_callback(func(): popup_panel.visible = false)
"

"extends Node3D

# world.gd
# Main world orchestrator: hooks up Mars discoveries to the HUD.

@onready var mars: PlanetGravity = $Mars
@onready var hud: CanvasLayer = $HUD

func _ready() -> void:
	# Connect POI signals to HUD
	for child in mars.find_children("*", "POIMarker", true, false):
		var poi := child as POIMarker
		poi.discovered.connect(_on_poi_discovered)

func _on_poi_discovered(title: String, fact: String) -> void:
	if hud and hud.has_method("show_discovery"):
		hud.show_discovery(title, fact)
"

