function Get-GlbAnimations($path) {
    Write-Host 'Checking:' $path
    $bytes = [System.IO.File]::ReadAllBytes($path)
    $jsonLength = [System.BitConverter]::ToUInt32($bytes, 12)
    $jsonBytes = New-Object byte[] $jsonLength
    [System.Array]::Copy($bytes, 20, $jsonBytes, 0, $jsonLength)
    $jsonStr = [System.Text.Encoding]::UTF8.GetString($jsonBytes)
    $json = $jsonStr | ConvertFrom-Json
    if ($json.animations) {
        Write-Host 'Animations count:' $json.animations.Count
        foreach ($a in $json.animations) {
            Write-Host ' - Animation:' $a.name
        }
    } else {
        Write-Host 'No animations found in this file.'
    }
}

