"@tool
extends SceneTree

func _init() -> void:
	var astro_scene = load("res://Assets/Rigged Astronaut by J-Toastie - 0oBRDJ9Zl9.glb")
	var inst: Node3D = astro_scene.instantiate()

	var anim_player = AnimationPlayer.new()
	anim_player.name = "AnimationPlayer"
	var lib = load("res://Assets/astronaut_animations.tres")
	anim_player.add_animation_library("", lib)
	inst.add_child(anim_player)
	anim_player.owner = inst

	# Ensure all children are owned so PackedScene saves them properly
	_set_owner_recursive(inst, inst)

	var packed = PackedScene.new()
	var pack_err = packed.pack(inst)
	if pack_err == OK:
		var save_err = ResourceSaver.save(packed, "res://Scenes/player/astronaut_model.tscn")
		print("Saved astronaut_model.tscn: ", save_err == OK)
	else:
		printerr("Failed to pack scene: ", pack_err)

	quit()

func _set_owner_recursive(node: Node, root: Node) -> void:
	for child in node.get_children():
		child.owner = root
		_set_owner_recursive(child, root)
"

