		if screen_light:
			screen_light.light_energy = 2.5

func _on_body_exited(body: Node3D) -> void:
	if body.is_in_group("player"):
		player_nearby = false
		if is_open:
			toggle_terminal()
		if prompt_label:
			prompt_label.visible = false
		if screen_light:
			screen_light.light_energy = 1.0
