func _is_inside_cave_hole(dir: Vector3) -> bool:
	for pit in CAVE_PITS:
		var center: Vector3 = (pit["dir"] as Vector3).normalized()
		var hole_rad: float = pit.get("hole_radius_rad", 0.018)
