"extends SceneTree

func _init() -> void:
	var r: Node3D = load("res://Assets/rocket_ship.glb").instantiate()
	var aabb: AABB = _calc_aabb(r)
	print("Combined AABB of rocket_ship.glb: ", aabb)
	print("Size: ", aabb.size, " Bottom Y: ", aabb.position.y, " Top Y: ", aabb.end.y)
	r.free()
	quit()

func _calc_aabb(n: Node) -> AABB:
	var total_aabb := AABB()
	var first := true
	var stack: Array[Node] = [n]
	while not stack.is_empty():
		var curr = stack.pop_back()
		if curr is MeshInstance3D and curr.mesh:
			var mesh_aabb = curr.mesh.get_aabb()
			# Transform mesh aabb into root space if needed
			if first:
				total_aabb = mesh_aabb
				first = false
			else:
				total_aabb = total_aabb.merge(mesh_aabb)
		for c in curr.get_children():
			stack.push_back(c)
	return total_aabb
