	var tangent = up_norm.cross(Vector3.FORWARD).normalized()
	if tangent.length_squared() < 0.01:
		tangent = up_norm.cross(Vector3.RIGHT).normalized()
	var bitangent = tangent.cross(up_norm).normalized()
	tangent = up_norm.cross(bitangent).normalized()

	# Compute safe Camera C position using local surface query:
	var horizontal_offset = tangent * 18.0 + bitangent * 14.0
	var cam_dir = (target_surf + horizontal_offset).normalized()
	var local_surf = planet.get_surface_point(cam_dir)
	var local_norm = local_surf.normalized()

	# Place 3.2m above local ground
	var safe_cam_c_12 = local_surf + local_norm * 3.5
	var safe_cam_c_16 = local_surf + local_norm * 4.2

	print("Local ground at Cam C spot: ", local_surf.length())
	print("Safe Cam C 12s height: ", safe_cam_c_12.length(), " (alt: ", safe_cam_c_12.length() - local_surf.length(), ")")
	print("Safe Cam C 16s height: ", safe_cam_c_16.length(), " (alt: ", safe_cam_c_16.length() - local_surf.length(), ")")

	# Check look angle to target_surf + up_norm * 2.0 (wreck base):
	var wreck_focus = target_surf + up_norm * 2.0
	var look_dir = (wreck_focus - safe_cam_c_12).normalized()
	print("Distance to wreck: ", safe_cam_c_12.distance_to(wreck_focus))
	print("Look direction: ", look_dir)

	# Check Camera D at 16s
	var d_h_offset = tangent * 20.0 + bitangent * 18.0
	var d_surf_16 = planet.get_surface_point((target_surf + d_h_offset).normalized())
	var safe_cam_d_16 = d_surf_16 + d_surf_16.normalized() * 7.0
	print("Safe Cam D 16s alt: ", safe_cam_d_16.length() - d_surf_16.length())

	quit()
	return true
"

