func _process(_delta: float) -> bool:
	var cs = load("res://intro_cutscene.tscn").instantiate()
	root.add_child(cs)
	var planet = cs.get_node("ProceduralMars")
	var target_surf = cs.final_surface_pt
	var up_norm = cs.surface_normal

	var tangent = up_norm.cross(Vector3.FORWARD).normalized()
	if tangent.length_squared() < 0.01:
		tangent = up_norm.cross(Vector3.RIGHT).normalized()
	var bitangent = tangent.cross(up_norm).normalized()
	tangent = up_norm.cross(bitangent).normalized()

	var get_safe_pos = func(h_offset: Vector3, h_above: float) -> Vector3:
		var dir = (target_surf + h_offset).normalized()
		var surf = planet.get_surface_point(dir)
		return surf + surf.normalized() * h_above

	var c_12 = get_safe_pos.call(tangent * 18.0 + bitangent * 14.0, 3.5)
	var c_16 = get_safe_pos.call(tangent * 18.0 + bitangent * 14.0, 4.2)

	var d_16 = get_safe_pos.call(tangent * 18.0 + bitangent * 16.0, 7.0)
	var d_24 = get_safe_pos.call(-tangent * 24.0 + bitangent * 22.0, 11.0)
	var d_32 = get_safe_pos.call(-tangent * 32.0 - bitangent * 18.0, 16.0)
	var d_40 = get_safe_pos.call(tangent * 38.0 - bitangent * 28.0, 20.0)

	var check_alt = func(name: String, pos: Vector3):
		var surf = planet.get_surface_point(pos.normalized())
		var alt = pos.length() - surf.length()
		print(name, " altitude above local ground: ", alt, " m")
		assert(alt >= 3.0, "Altitude must be at least 3.0m!")

	check_alt.call("Cam C (12s)", c_12)
	check_alt.call("Cam C (16s)", c_16)
	check_alt.call("Cam D (16s)", d_16)
	check_alt.call("Cam D (24s)", d_24)
	check_alt.call("Cam D (32s)", d_32)
	check_alt.call("Cam D (40s)", d_40)

	print("ALL CAMERA ALTITUDES VERIFIED ABOVE GROUND!")
	quit()
	return true
"

