	print("Angle 30: ", rad_to_deg(fwd.signed_angle_to(to_pod_30, up)))

	var to_pod_minus30 = fwd.rotated(up, deg_to_rad(-30.0))
	print("Angle -30: ", rad_to_deg(fwd.signed_angle_to(to_pod_minus30, up)))
	quit(0)
